begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(14);
insert into auth.users(id) values('72000000-0000-0000-0000-000000000001'),('72000000-0000-0000-0000-000000000002');
insert into public.users(id,username,is_admin) values('72000000-0000-0000-0000-000000000001','mfa_admin',true),('72000000-0000-0000-0000-000000000002','mfa_other',false);
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values('72000000-0000-0000-0000-000000000003','72000000-0000-0000-0000-000000000001','totp','verified',now(),now());
insert into auth.sessions(id,user_id,aal,factor_id) values('72000000-0000-0000-0000-000000000004','72000000-0000-0000-0000-000000000001','aal2','72000000-0000-0000-0000-000000000003');
select ok(not has_function_privilege('anon','public.admin_auth_session_state(uuid,uuid)','execute'),'anon cannot inspect Auth sessions');
select ok(not has_function_privilege('authenticated','public.admin_auth_session_state(uuid,uuid)','execute'),'authenticated cannot inspect Auth sessions');
select ok(has_function_privilege('service_role','public.admin_auth_session_state(uuid,uuid)','execute'),'service can inspect bounded assurance');
set local role anon;
select throws_ok($$select public.admin_auth_session_state('72000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000004')$$,'42501',null,'anon execution rejected');
reset role;
set local role authenticated;
select throws_ok($$select public.admin_auth_session_state('72000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000004')$$,'42501',null,'authenticated execution rejected');
reset role;
set local role service_role;
select is(public.admin_auth_session_state('72000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000004'),'{"active":true,"aal":"aal2","factor_verified":true}'::jsonb,'live verified session has exactly three safe fields');
select is(public.admin_auth_session_state('72000000-0000-0000-0000-000000000002','72000000-0000-0000-0000-000000000004'),'{"active":false,"aal":null,"factor_verified":false}'::jsonb,'wrong actor cannot borrow a session');
select is(public.admin_auth_session_state('72000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000099')->>'active','false','absent session denied');
reset role;
update auth.sessions set aal='aal1',factor_id=null where id='72000000-0000-0000-0000-000000000004';
select is(public.admin_auth_session_state('72000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000004'),'{"active":true,"aal":"aal1","factor_verified":false}'::jsonb,'active AAL1 bootstrap is distinguishable from revoked session');
update auth.sessions set aal='aal2',factor_id='72000000-0000-0000-0000-000000000003' where id='72000000-0000-0000-0000-000000000004';
update auth.mfa_factors set status='unverified' where id='72000000-0000-0000-0000-000000000003';
select is(public.admin_auth_session_state('72000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000004')->>'factor_verified','false','unverified factor rejects stale AAL2');
update auth.mfa_factors set status='verified' where id='72000000-0000-0000-0000-000000000003';
update auth.sessions set not_after=now()-interval '1 second' where id='72000000-0000-0000-0000-000000000004';
select is(public.admin_auth_session_state('72000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000004'),'{"active":false,"aal":null,"factor_verified":false}'::jsonb,'expired session denied');
update auth.sessions set not_after=null where id='72000000-0000-0000-0000-000000000004';
update public.users set is_admin=false where id='72000000-0000-0000-0000-000000000001';
select is(public.admin_auth_session_state('72000000-0000-0000-0000-000000000001','72000000-0000-0000-0000-000000000004')->>'active','false','revoked administrator role denied');
select ok(not has_table_privilege('service_role','auth.sessions','select'),'no new raw Auth session grant');
select is((select array_to_string(proconfig,',') from pg_proc where oid='public.admin_auth_session_state(uuid,uuid)'::regprocedure),'search_path=""','definer uses empty search path');
select * from finish();
rollback;
